#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int t;
    int p;
} Item;

int cmp_items(const void *a, const void *b) {
    const Item *ia = (const Item *)a;
    const Item *ib = (const Item *)b;
    if (ia->t != ib->t) {
        return ia->t - ib->t;
    }
    return (ia->p > ib->p) - (ia->p < ib->p);
}

static Item items[100005];
static int start_idx[100005];
static int end_idx[100005];
static int cur_idx[100005];

static int heap[100005];
static int pos_in_heap[100005];
static int heap_size = 0;

int heap_less(int type_a, int type_b) {
    int price_a = items[cur_idx[type_a]].p;
    int price_b = items[cur_idx[type_b]].p;
    if (price_a != price_b) {
        return price_a < price_b;
    }
    return type_a < type_b;
}

void swap_heap_nodes(int i, int j) {
    int temp = heap[i];
    heap[i] = heap[j];
    heap[j] = temp;
    pos_in_heap[heap[i]] = i;
    pos_in_heap[heap[j]] = j;
}

void sift_up(int i) {
    while (i > 1 && heap_less(heap[i], heap[i / 2])) {
        swap_heap_nodes(i, i / 2);
        i = i / 2;
    }
}

void sift_down(int i) {
    while (2 * i <= heap_size) {
        int left = 2 * i;
        int right = 2 * i + 1;
        int smallest = i;

        if (left <= heap_size && heap_less(heap[left], heap[smallest])) {
            smallest = left;
        }
        if (right <= heap_size && heap_less(heap[right], heap[smallest])) {
            smallest = right;
        }

        if (smallest != i) {
            swap_heap_nodes(i, smallest);
            i = smallest;
        } else {
            break;
        }
    }
}

void push(int type) {
    heap_size++;
    heap[heap_size] = type;
    pos_in_heap[type] = heap_size;
    sift_up(heap_size);
}

