    int type_to_remove = heap[i];
    pos_in_heap[type_to_remove] = 0;

    if (i == heap_size) {
        heap_size--;
        return;
    }

    heap[i] = heap[heap_size];
    pos_in_heap[heap[i]] = i;
    heap_size--;

    sift_down(i);
    sift_up(i);
}

