            if (cur_idx[u] < end_idx[u]) {
                total_revenue += items[cur_idx[u]].p;
                cur_idx[u]++;
                if (cur_idx[u] < end_idx[u]) {
                    sift_down(pos_in_heap[u]);
                } else {
                    remove_node(pos_in_heap[u]);
                }
            }
        } else {
            if (heap_size > 0) {
                int best_type = heap[1];
                total_revenue += items[cur_idx[best_type]].p;
