#define INF 2000000000

typedef struct {
    int type;
    int price;
} Item;

typedef struct {
    int price;
    int type;
} Node;

static inline Node combine(Node a, Node b) {
    if (a.price < b.price) return a;
    if (b.price < a.price) return b;
    if (a.type < b.type) return a;
    return b;
}

int cmp_items(const void *a, const void *b) {
    const Item *ia = (const Item *)a;
    const Item *ib = (const Item *)b;
    if (ia->type != ib->type) {
        return (ia->type < ib->type) ? -1 : 1;
    }
    if (ia->price != ib->price) {
        return (ia->price < ib->price) ? -1 : 1;
    }
    return 0;
}

#define MAX_T 100005

Node tree[4 * MAX_T];
int start_idx[MAX_T];
int end_idx[MAX_T];
int cur_idx[MAX_T];

void build(int node, int l, int r, Item *items) {
    if (l == r) {
        if (cur_idx[l] < end_idx[l]) {
            tree[node] = (Node){items[cur_idx[l]].price, l};
        } else {
            tree[node] = (Node){INF, INF};
        }
        return;
    }
    int mid = (l + r) / 2;
    build(2 * node, l, mid, items);
    build(2 * node + 1, mid + 1, r, items);
    tree[node] = combine(tree[2 * node], tree[2 * node + 1]);
}

void update(int node, int l, int r, int pos, Item *items) {
    if (l == r) {
        if (cur_idx[l] < end_idx[l]) {
            tree[node] = (Node){items[cur_idx[l]].price, l};
        } else {
            tree[node] = (Node){INF, INF};
        }
        return;
    }
    int mid = (l + r) / 2;
    if (pos <= mid) {
        update(2 * node, l, mid, pos, items);
    } else {
        update(2 * node + 1, mid + 1, r, pos, items);
    }
    tree[node] = combine(tree[2 * node], tree[2 * node + 1]);
}

